const resolveImage = `-- name: ResolveImage :one
SELECT file_key, content_type
FROM email_images
WHERE token = $1::text AND status = 'ACTIVE'
`

type ResolveImageRow struct {
	FileKey     string
	ContentType string
}

// Serves the public route. Deliberately not scoped by tenant: the token is
// the only credential, because the recipient's mail client has no session.
// That is why the token is random and why withdrawing one has to work.
func (q *Queries) ResolveImage(ctx context.Context, token string) (ResolveImageRow, error) {
	row := q.db.QueryRow(ctx, resolveImage, token)
	var i ResolveImageRow
	err := row.Scan(&i.FileKey, &i.ContentType)
	return i, err
}

const reviveStuckSending = `-- name: ReviveStuckSending :execrows
UPDATE email_messages
SET status = 'SEND_UNKNOWN',
    attention_reason = '发送超时，无法确定是否已发出——请人工确认后决定重发或放弃'
WHERE tenant_id = $1::bigint
  AND status = 'SENDING'
  AND queued_at < now() - ($2::int || ' seconds')::interval
`

type ReviveStuckSendingParams struct {
	TenantID      int64
	WindowSeconds int32
}

// A message left in SENDING past the decision window means the process died
// between the call and the response: we cannot tell whether it went out.
// It becomes SEND_UNKNOWN rather than being silently retried.
func (q *Queries) ReviveStuckSending(ctx context.Context, arg ReviveStuckSendingParams) (int64, error) {
	result, err := q.db.Exec(ctx, reviveStuckSending, arg.TenantID, arg.WindowSeconds)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const saveDraft = `-- name: SaveDraft :one

INSERT INTO email_drafts (
    id, tenant_id, owner_id, subject, body, body_format,
    signature_id, kind, recipients, attachments,
    send_mode, cc, bcc, reply_to_inbound_id, forward_inbound_id
) VALUES (
    coalesce(nullif($1::bigint, 0), nextval('email_drafts_id_seq')),
    $2::bigint,
    $3::bigint,
    $4::text,
    $5::text,
    $6::text,
    $7::bigint,
    $8::text,
    $9::jsonb,
    $10::jsonb,
    $11::text,
    $12::jsonb,
    $13::jsonb,
    $14::bigint,
    $15::bigint
)
ON CONFLICT (id) DO UPDATE SET
    subject = excluded.subject,
    body = excluded.body,
    body_format = excluded.body_format,
    signature_id = excluded.signature_id,
    kind = excluded.kind,
    recipients = excluded.recipients,
    attachments = excluded.attachments,
    bcc = excluded.bcc,
    send_mode = excluded.send_mode,
    cc = excluded.cc,
    reply_to_inbound_id = excluded.reply_to_inbound_id,
    forward_inbound_id = excluded.forward_inbound_id,
    updated_at = now()
WHERE email_drafts.tenant_id = $2::bigint
  AND email_drafts.owner_id = $3::bigint
RETURNING id
`

type SaveDraftParams struct {
	ID               int64
	TenantID         int64
	OwnerID          int64
	Subject          string
	Body             string
	BodyFormat       string
	SignatureID      int64
	Kind             string
	Recipients       []byte
	Attachments      []byte
	SendMode         string
	Cc               []byte
	Bcc              []byte
	ReplyToInboundID int64
	ForwardInboundID int64
}

// ------------------------------------------------------------------ drafts
// Upsert on id: the composer autosaves, so this runs repeatedly for one
// draft and must not accumulate rows.
// The owner check is in the WHERE, not just the parameters: without it an
// upsert with somebody else's id would silently overwrite their draft.
func (q *Queries) SaveDraft(ctx context.Context, arg SaveDraftParams) (int64, error) {
	row := q.db.QueryRow(ctx, saveDraft,
		arg.ID,
		arg.TenantID,
		arg.OwnerID,
		arg.Subject,
		arg.Body,
		arg.BodyFormat,
		arg.SignatureID,
		arg.Kind,
		arg.Recipients,
		arg.Attachments,
		arg.SendMode,
		arg.Cc,
		arg.Bcc,
		arg.ReplyToInboundID,
		arg.ForwardInboundID,
	)
	var id int64
	err := row.Scan(&id)
	return id, err
}

const sumAttachmentSize = `-- name: SumAttachmentSize :one
SELECT coalesce(sum(file_size), 0)::bigint AS total_bytes
FROM email_attachments
WHERE tenant_id = $1::bigint
  AND campaign_id = $2::bigint
`

type SumAttachmentSizeParams struct {
	TenantID   int64
	CampaignID int64
}

// Guards the per-send total. Recipient servers commonly refuse anything much
// over 25 MB, and the refusal arrives as a bounce per recipient rather than
// as one error at compose time.
func (q *Queries) SumAttachmentSize(ctx context.Context, arg SumAttachmentSizeParams) (int64, error) {
	row := q.db.QueryRow(ctx, sumAttachmentSize, arg.TenantID, arg.CampaignID)
	var total_bytes int64
	err := row.Scan(&total_bytes)
	return total_bytes, err
}

const suppressedAmong = `-- name: SuppressedAmong :many
SELECT email, reason FROM email_suppressions
WHERE tenant_id = $1::bigint
  AND email = ANY($2::text[])
`

type SuppressedAmongParams struct {
	TenantID int64
	Emails   []string
}

type SuppressedAmongRow struct {
	Email  string
	Reason string
}

// Checked before queueing, in one round trip for the whole recipient list.
func (q *Queries) SuppressedAmong(ctx context.Context, arg SuppressedAmongParams) ([]SuppressedAmongRow, error) {
	rows, err := q.db.Query(ctx, suppressedAmong, arg.TenantID, arg.Emails)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SuppressedAmongRow
	for rows.Next() {
		var i SuppressedAmongRow
		if err := rows.Scan(&i.Email, &i.Reason); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

